const items=[{id:'credo-ai',name:'Credo AI'},{id:'holistic-ai',name:'Holistic AI'},{id:'trustible',name:'Trustible'},{id:'enzai',name:'Enzai'},{id:'saidot',name:'Saidot'},{id:'lumenova-ai',name:'Lumenova AI'},{id:'monitaur',name:'Monitaur'},{id:'asenion',name:'Asenion'},{id:'verifywise',name:'VerifyWise'}];
const schema=JSON.stringify({type:'object',properties:{id:{type:'string'},name:{type:'string'},official_summary:{type:'string'},capabilities:{type:'array',items:{type:'string'}},deployment_claims:{type:'array',items:{type:'string'}},ai_governance_scope:{type:'array',items:{type:'string'}},commercial_evidence:{type:'array',items:{type:'string'}},official_sources:{type:'array',items:{type:'string'}},evidence_quality:{type:'string'},limitations:{type:'string'}},required:['id','name','official_summary','capabilities','deployment_claims','ai_governance_scope','commercial_evidence','official_sources','evidence_quality','limitations']});
const mapped=await parallel('منصات منافسة: مصادر رسمية فقط',()=>items.map(item=>agent('Research exactly '+item.name+' using only official public company/product/docs/blog pages and official source repositories where relevant. Open/read multiple URLs; no snippets-only conclusions. Report officially claimed, not independently tested, capabilities across registry, policy packs, agents, evaluation, monitoring, enforcement, evidence/audit, deployment. Include public pricing/commercial facts only if explicitly shown, otherwise say unknown. Include direct source URLs and access-related limitations; no superiority or market-share inference. Return concise Arabic fields id='+item.id+', name, official_summary, capabilities[], deployment_claims[], ai_governance_scope[], commercial_evidence[], official_sources[], evidence_quality, limitations. Do not create files.',{brief:'مصادر رسمية لمنصة '+item.name,sandbox:'shared',effort_level:'lite',schema})),{schema});
const successful=mapped.filter(r=>r.ok).map(r=>r.value); const failures=mapped.map((r,i)=>r.ok?null:{id:items[i].id,code:r.error.code,message:r.error.message}).filter(Boolean);
